import Foundation

/// Barlow and Barlow Semi Condensed, embedded in the blocked page so it needs no network and no files.
/// Copyright 2017 The Barlow Project Authors (https://github.com/jpt/barlow), SIL Open Font License 1.1
/// (Resources/Fonts/Barlow-OFL.txt). Taken from @fontsource/barlow and @fontsource/barlow-semi-condensed 5.3.0,
/// subset to Latin-1 plus curly quotes, dashes and the ellipsis, unhinted:
///   pyftsubset <font>.woff2 --unicodes="U+0020-007E,U+00A0-00FF,U+2013-2014,U+2018-201D,U+2026,U+2022,U+2212"
///     --flavor=woff2 --layout-features="kern,tnum" --no-hinting --desubroutinize
/// Regular and SemiBold Barlow for reading, SemiBold and Bold Semi Condensed for headings and times.
enum BlockedPageFonts {
    static let css = ##"""
@font-face{font-family:"Barlow";font-style:normal;font-weight:400;font-display:block;src:url(data:font/woff2;base64,) format("woff2")}
@font-face{font-family:"Barlow";font-style:normal;font-weight:600;font-display:block;src:url(data:font/woff2;base64,) format("woff2")}
@font-face{font-family:"Barlow Semi Condensed";font-style:normal;font-weight:600;font-display:block;src:url(data:font/woff2;base64,) format("woff2")}
@font-face{font-family:"Barlow Semi Condensed";font-style:normal;font-weight:700;font-display:block;src:url(data:font/woff2;base64,) format("woff2")}
"""##
}
